package com.bank.ref;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ReferenceCodeDemo {
    private static final Logger log = Logger.getLogger(ReferenceCodeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        ReferenceCodeService svc = new ReferenceCodeService();

        // 'A' + 1 is int arithmetic → 66, NOT the letter B.
        int raw = svc.charExprValue('A', 1);
        log.info(() -> "'A' + 1 as int = " + raw + " (promotion to int)");

        // Cast back to char to get the actual letter 'B'.
        char cc = svc.checkChar('A', 1);
        log.info(() -> "checkChar('A',1) = " + cc + " (cast int result back to char)");

        // Non-constant expression would NOT compile without the cast:
        //   int one = 1; char x = 'A' + one;   // COMPILE ERROR
        //   char x = (char)('A' + one);         // OK with cast
        // Constant expression that fits DOES compile without a cast:
        char constOk = 'A' + 1;                 // compiler folds to 66, fits char
        log.fine(() -> "constant 'A' + 1 folded to char = " + constOk);

        // long + float promotes to float → precision loss for big longs.
        long accountCount = 9_000_000_001L;
        float rate = 0.0725f;
        float promoted = svc.blendedRatePromotion(accountCount, rate);
        log.warning(() -> "long+float promoted (float) = " + promoted
                + " (precision risk)");

        // Correct money-adjacent math uses BigDecimal.
        BigDecimal correct = svc.blendedRateBigDecimal(accountCount, new BigDecimal("0.0725"));
        log.info(() -> "BigDecimal blended = " + correct + " (exact)");

        log.info(() -> "Balance stays BigDecimal: " + rajesh.getBalance());
    }
}

