class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in service/ReferenceCodeService.java in a real project ───
class ReferenceCodeService {
    private static final Logger log = Logger.getLogger(ReferenceCodeService.class.getName());

    // char + int promotes to int; this returns the raw int value.
    int charExprValue(char base, int offset) {
        return base + offset;   // promotion: char -> int, result int
    }

    // Must cast the int result back to char to get a character.
    char checkChar(char base, int offset) {
        int sum = base + offset;    // int
        return (char) sum;          // explicit narrowing cast required
    }

    // long + float yields float (float outranks long) — precision risk.
    float blendedRatePromotion(long count, float rate) {
        return count + rate;   // long promoted to float, result float
    }

    // Correct approach for any money-adjacent math: BigDecimal.
    BigDecimal blendedRateBigDecimal(long count, BigDecimal rate) {
        return new BigDecimal(count).add(rate).setScale(4, RoundingMode.HALF_UP);
    }
}

